const destinationNames:Record<string,string>={china:'China','south-korea':'South Korea',thailand:'Thailand',vietnam:'Vietnam',indonesia:'Indonesia'};
const interestKeys=['food','history','nature','art','active','wellness','family','celebration'];
const formatMoney=(prices:Record<string,number>,locale:Locale)=>{const currency=locale==='da'?'DKK':locale==='sv'?'SEK':locale==='no'?'NOK':locale==='hu'?'HUF':'EUR';return new Intl.NumberFormat(locale,{style:'currency',currency,maximumFractionDigits:0}).format(prices[currency])};
const formatEstimateMoney=(amount:number,currency:string,locale:Locale)=>new Intl.NumberFormat(locale,{style:'currency',currency,maximumFractionDigits:0}).format(amount);

const builderCopy={title:'Build this journey around you',intro:'Choose the hotel and daily experience that feels most like you. Leave a decision open or write your own idea—every choice travels with the plan to your consultant.',hotels:'Choose your hotels',hotelIntro:'Well-reviewed options matched to your selected standard. Availability and final room category will be checked by your consultant.',days:'Shape each day',dayIntro:'Pick one direction for each day, leave it open, or add your own idea.',recommended:'Recommended fit',room:'Room guidance',reviews:'Review signal',sources:'Research sources',choose:'Choose this hotel',ownHotel:'I have another hotel or room preference',ownDay:'Write my own idea for this day',openDay:'Leave this day open for the consultant',progress:'decisions made',review:'Your selected journey',notChosen:'Not decided yet'};

interface BuilderChoices {hotels:Record<string,string>;hotelNotes:Record<string,string>;days:Record<string,string>;dayNotes:Record<string,string>}
const emptyChoices=():BuilderChoices=>({hotels:{},hotelNotes:{},days:{},dayNotes:{}});
const recommendedChoices=(suggestion:TripSuggestion,budget:TripPlannerBudget):BuilderChoices=>({
  hotels:(suggestion.hotelStays??[]).reduce<Record<string,string>>((selected,stay,index)=>{const option=stay.options.find(candidate=>hotelOptionMatchesBudget(candidate,budget));if(option)selected[`stay-${index}`]=option.id;return selected},{}),
  hotelNotes:{},
  days:(suggestion.dayPlans??[]).reduce<Record<string,string>>((selected,day)=>{if(day.options[0])selected[`day-${day.day}`]=day.options[0].id;return selected},{}),
  dayNotes:{},
});

export default function TripPlanner({locale='en'}:{locale?:Locale}){
  const c:Record<string,string>={...(copy[locale]??copy.en),intro:agentIntro[locale]??agentIntro.en};
  const a=agentCopy[locale]??agentCopy.en;
  const routeCopy=routeDetailCopy[locale]??routeDetailCopy.en;
  const [suggestion,setSuggestion]=useState<TripSuggestion|null>(null);
  const [profile,setProfile]=useState<Record<string,unknown>|null>(null);
  const [status,setStatus]=useState<'idle'|'loading'|'error'>('idle');
  const [error,setError]=useState('');
  const [handoffStatus,setHandoffStatus]=useState<'idle'|'sending'|'sent'|'error'>('idle');
  const [handoffUrl,setHandoffUrl]=useState('');
  const [duration,setDuration]=useState(12);
  const [loadingStep,setLoadingStep]=useState(0);
  const [choices,setChoices]=useState<BuilderChoices>(emptyChoices);
  const destinations=useMemo(()=>Object.entries(destinationNames),[]);
  useEffect(()=>{
    if(status!=='loading'){setLoadingStep(0);return}
    document.querySelector('[data-planner-loading]')?.scrollIntoView({behavior:'smooth',block:'center'});
    const timer=window.setInterval(()=>setLoadingStep(step=>Math.min(step+1,3)),4500);
    return ()=>window.clearInterval(timer);
  },[status]);
  async function requestSuggestion(body:Record<string,unknown>){
    const response=await fetch('/api/trip-suggestion',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=response.headers.get('content-type')?.includes('application/json')?await response.json() as {suggestion?:TripSuggestion;error?:string;code?:string}:null;if(!response.ok||!result?.suggestion)throw new Error(result?.code==='AI_LIMIT'?a.capacityError:result?.error||'We could not prepare a suggestion just now. Please try again.');const budget=String(body.budget||'comfort') as TripPlannerBudget;const suggestion={...result.suggestion,hotelStays:(result.suggestion.hotelStays??[]).map(stay=>({...stay,options:stay.options.filter(option=>hotelOptionMatchesBudget(option,budget))}))};setSuggestion(suggestion);setChoices(recommendedChoices(suggestion,budget));setStatus('idle');requestAnimationFrame(()=>document.querySelector('[data-trip-result]')?.scrollIntoView({behavior:'smooth',block:'start'}));
  }
  async function submit(event:SyntheticEvent<HTMLFormElement,SubmitEvent>){
    event.preventDefault();const data=new FormData(event.currentTarget);const interests=data.getAll('interests').map(String);const destinationIdeas=String(data.get('destinationIdeas')||'').trim();const notes=String(data.get('notes')||'').trim();if(!interests.length&&!destinationIdeas&&!notes){setError(a.inputError);setStatus('error');return}
    setStatus('loading');setError('');const body={locale,destinations:data.getAll('destinations').map(String),destinationIdeas,travelMonth:String(data.get('travelMonth')||'flexible'),durationDays:duration,adults:Number(data.get('adults')),children:Number(data.get('children')),budget:String(data.get('budget')),pace:String(data.get('pace')),interests,notes};setProfile(body);
    try{await requestSuggestion(body)}catch(reason){setError(reason instanceof Error?reason.message:'Unable to create a suggestion.');setStatus('error')}
  }
  async function refine(event:SyntheticEvent<HTMLFormElement,SubmitEvent>){
    event.preventDefault();if(!profile||!suggestion)return;const form=event.currentTarget;const data=new FormData(form);const refinement=String(data.get('refinement')||'').trim();if(!refinement){setError(a.inputError);setStatus('error');return}setStatus('loading');setError('');
    try{await requestSuggestion({...profile,currentSuggestion:suggestion,refinement});form.reset()}catch(reason){setError(reason instanceof Error?reason.message:'Unable to refine the suggestion.');setStatus('error')}
  }
  async function handoff(event:SyntheticEvent<HTMLFormElement,SubmitEvent>){
    event.preventDefault();if(!suggestion)return;const form=event.currentTarget;const data=new FormData(form);setHandoffStatus('sending');
    try{const response=await fetch('/api/trip-enquiry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({locale,name:data.get('name'),email:data.get('email'),phone:data.get('phone'),message:data.get('message'),website:data.get('website'),consent:data.get('consent')==='yes',suggestion,profile,builderChoices:choices})});const result=await response.json() as {ok?:boolean;proposalUrl?:string};if(!response.ok||!result.ok||!result.proposalUrl)throw new Error();setHandoffUrl(result.proposalUrl);setHandoffStatus('sent')}catch{setHandoffStatus('error')}
  }
  if(suggestion){
    const h=handoffCopy[locale]??handoffCopy.en!;
    const x=conversionCopy[locale]??conversionCopy.en;
    const priceCopy=estimateCopy[locale]??estimateCopy.en;
    const hotelStays=suggestion.hotelStays??[];
    const dayPlans=suggestion.dayPlans??[];
    const totalDecisions=hotelStays.length+dayPlans.length;
    const completedDecisions=Object.keys(choices.hotels).length+Object.keys(choices.days).length;
    return <article className="trip-result" data-trip-result aria-live="polite">
      <header className="result-hero"><div><span className="agent-mark">{x.workspace}</span><h2>{suggestion.title}</h2><p>{suggestion.summary}</p><div className="result-meta"><span>{suggestion.recommendedDuration}</span><span>{x.researched}</span>{!suggestion.matchedJourneys.length&&<span>{a.tailorMade}</span>}<span>{c.notice}</span></div></div><aside className="result-actions">{suggestion.priceEstimate&&<section className="price-estimate" aria-label={priceCopy.eyebrow}><span>{priceCopy.eyebrow}</span><small>{priceCopy.total}</small><strong>{formatEstimateMoney(suggestion.priceEstimate.totalLow,suggestion.priceEstimate.currency,locale)}–{formatEstimateMoney(suggestion.priceEstimate.totalHigh,suggestion.priceEstimate.currency,locale)}</strong><p><b>{formatEstimateMoney(suggestion.priceEstimate.perAdultLow,suggestion.priceEstimate.currency,locale)}–{formatEstimateMoney(suggestion.priceEstimate.perAdultHigh,suggestion.priceEstimate.currency,locale)}</b> {priceCopy.perAdult}</p><details><summary>{estimateDetailsLabel[locale]??estimateDetailsLabel.en}</summary><p>{priceCopy.includes}</p><p>{priceCopy.excludes}</p></details><em>{priceCopy.caveat}</em></section>}<a className="btn result-cta" href="#consultant-request">{x.proposal} ↘</a></aside></header>
      <div className="result-grid"><section><div className="section-heading"><span>01</span><h3>{c.route}</h3></div><ol className="route-list">{suggestion.route.map((stop,index)=><li key={`${stop.days}-${index}`}><span>{stop.days}</span><div><b>{stop.place}</b><p>{stop.focus}</p><small>{routeCopy.highlights}</small><ul>{stop.highlights.map(item=><li key={item}>{item}</li>)}</ul>{stop.onwardTravel&&<p className="onward"><strong>{routeCopy.onward}:</strong> {stop.onwardTravel}</p>}</div></li>)}</ol></section><aside><div className="insight-card"><span>02</span><section><h3>{c.fit}</h3><ul>{suggestion.fitReasons.map(item=><li key={item}>{item}</li>)}</ul></section><section><h3>{c.notesTitle}</h3><ul>{suggestion.practicalNotes.map(item=><li key={item}>{item}</li>)}</ul></section></div><a className="proposal-card" href="#consultant-request"><small>{x.complete}</small><strong>{x.proposal}</strong><span>↘</span></a></aside></div>
      {(hotelStays.length>0||dayPlans.length>0)&&<section className="journey-builder"><header><div><span className="agent-mark">Journey Designer · make it yours</span><h3>{builderCopy.title}</h3><p>{builderCopy.intro}</p></div><div className="builder-progress"><strong>{completedDecisions}/{totalDecisions}</strong><span>{builderCopy.progress}</span><progress max={Math.max(1,totalDecisions)} value={completedDecisions}/></div></header>
        {hotelStays.length>0&&<div className="builder-block"><div className="builder-heading"><span>03</span><div><h4>{builderCopy.hotels}</h4><p>{builderCopy.hotelIntro}</p></div></div><div className="stay-list">{hotelStays.map((stay,stayIndex)=>{const stayKey=`stay-${stayIndex}`;return <fieldset className="stay-choice" key={stayKey}><legend><b>{stay.place}</b><span>{stay.nights} night{stay.nights===1?'':'s'}</span></legend><div className="hotel-options">{stay.options.map(option=><label className="hotel-card" key={option.id}><input type="radio" name={stayKey} value={option.id} checked={choices.hotels[stayKey]===option.id} onChange={()=>setChoices(current=>({...current,hotels:{...current.hotels,[stayKey]:option.id}}))}/><span className="selection-mark">✓</span><small>{option.standard} · {option.area}</small><strong>{option.name}</strong><p>{option.whyFit}</p><dl><div><dt>{builderCopy.room}</dt><dd>{option.roomGuidance}</dd></div><div><dt>{builderCopy.reviews}</dt><dd>{option.reviewSignal}</dd></div></dl>{option.sources.length>0&&<div className="option-sources"><span>{builderCopy.sources}</span>{option.sources.map(source=><a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.domain} ↗</a>)}</div>}<em>{builderCopy.choose}</em></label>)}</div><label className="custom-choice"><input type="radio" name={stayKey} value="custom" checked={choices.hotels[stayKey]==='custom'} onChange={()=>setChoices(current=>({...current,hotels:{...current.hotels,[stayKey]:'custom'}}))}/><span>{builderCopy.ownHotel}</span><textarea aria-label={`${builderCopy.ownHotel} — ${stay.place}`} rows={2} maxLength={500} value={choices.hotelNotes[stayKey]??''} onFocus={()=>setChoices(current=>({...current,hotels:{...current.hotels,[stayKey]:'custom'}}))} onChange={event=>setChoices(current=>({...current,hotels:{...current.hotels,[stayKey]:'custom'},hotelNotes:{...current.hotelNotes,[stayKey]:event.target.value}}))}/></label></fieldset>})}</div></div>}
        {dayPlans.length>0&&<div className="builder-block day-builder"><div className="builder-heading"><span>04</span><div><h4>{builderCopy.days}</h4><p>{builderCopy.dayIntro}</p></div></div><div className="day-list">{dayPlans.map(day=>{const dayKey=`day-${day.day}`;return <fieldset className="day-choice" key={dayKey}><legend><span>Day {day.day}</span><div><b>{day.place}</b><small>{day.theme}</small></div></legend><div className="day-options">{day.options.map(option=><label key={option.id} className="day-option"><input type="radio" name={dayKey} value={option.id} checked={choices.days[dayKey]===option.id} onChange={()=>setChoices(current=>({...current,days:{...current.days,[dayKey]:option.id}}))}/><span className="selection-mark">✓</span><div><small>{option.type} · {option.interestTags.join(' · ')}</small><strong>{option.name}</strong><p>{option.description}</p><em>{option.whyFit}</em>{option.sources.length>0&&<div className="option-sources">{option.sources.map(source=><a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.domain} ↗</a>)}</div>}</div></label>)}</div><div className="day-alternatives"><label><input type="radio" name={dayKey} value="open" checked={choices.days[dayKey]==='open'} onChange={()=>setChoices(current=>({...current,days:{...current.days,[dayKey]:'open'}}))}/><span>{builderCopy.openDay}</span></label><label className="custom-choice"><input type="radio" name={dayKey} value="custom" checked={choices.days[dayKey]==='custom'} onChange={()=>setChoices(current=>({...current,days:{...current.days,[dayKey]:'custom'}}))}/><span>{builderCopy.ownDay}</span><textarea aria-label={`${builderCopy.ownDay} — Day ${day.day}`} rows={2} maxLength={500} value={choices.dayNotes[dayKey]??''} onFocus={()=>setChoices(current=>({...current,days:{...current.days,[dayKey]:'custom'}}))} onChange={event=>setChoices(current=>({...current,days:{...current.days,[dayKey]:'custom'},dayNotes:{...current.dayNotes,[dayKey]:event.target.value}}))}/></label></div></fieldset>})}</div></div>}
      </section>}
      {suggestion.travellerInsights.length>0&&<section className="traveller-research"><div className="section-heading"><span>03</span><div><h3>{routeCopy.travellers}</h3><p>{routeCopy.sourceNote}</p></div></div><ul>{suggestion.travellerInsights.map(item=><li key={item.insight}><span>{item.insight}</span><div>{item.sources.map(source=><a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.title} · {source.domain} ↗</a>)}</div></li>)}</ul></section>}
      <section className="agent-refinement"><header><span className="agent-mark">Journey Designer · refine</span><h3>{a.refineTitle}</h3><p>{a.refineIntro}</p></header><form onSubmit={refine}><textarea name="refinement" rows={3} maxLength={700} placeholder={a.refinePlaceholder} required/><button className="secondary" type="submit" disabled={status==='loading'}>{status==='loading'?a.refining:a.refineSubmit} ↗</button></form>{error&&<p className="form-error" role="alert">{error}</p>}</section>
      {suggestion.matchedJourneys.length>0&&<section className="matches"><h3>{c.matches}</h3><div>{suggestion.matchedJourneys.map(journey=><a href={journey.href} key={journey.slug}><span>{journey.country.replace('-', ' ')}</span><b>{journey.name}</b><small>{journey.duration} {c.daysLabel} · {c.from} {formatMoney(journey.prices,locale)}</small></a>)}</div></section>}
      <section className="consultant-handoff" id="consultant-request"><div className="handoff-story"><span className="agent-mark">Way to Asia · Consultant handoff</span><h3>{h.title}</h3><p>{h.intro}</p><div className="handoff-includes"><b>{x.includes}</b><span>✓ {x.route}</span><span>✓ {x.brief}</span><span>✓ Your {completedDecisions} hotel and day decisions</span><span>✓ {x.notes}</span></div><ol><li><span>1</span>{x.nextOne}</li><li><span>2</span>{x.nextTwo}</li><li><span>3</span>{x.nextThree}</li></ol></div><div className="handoff-panel">{handoffStatus==='sent'?<div className="handoff-success" role="status"><p>{h.sent}</p><a className="btn" href={handoffUrl}>{h.view??handoffCopy.en!.view} ↗</a></div>:<form onSubmit={handoff}><input name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" className="honeypot"/><label>{h.name}<input name="name" maxLength={160} required/></label><label>{h.email}<input name="email" type="email" maxLength={240} required/></label><label>{h.phone}<input name="phone" type="tel" maxLength={100}/></label><label>{h.message}<textarea name="message" rows={4} maxLength={1600}/></label><label className="consent"><input type="checkbox" name="consent" value="yes" required/><span>{h.consent}</span></label><button className="btn" type="submit" disabled={handoffStatus==='sending'}>{handoffStatus==='sending'?h.sending:h.send} ↗</button>{handoffStatus==='error'&&<p className="form-error" role="alert">{h.error}</p>}</form>}</div></section>
      <footer><button type="button" className="secondary" onClick={()=>{setSuggestion(null);setProfile(null);setChoices(emptyChoices());setError('');setHandoffStatus('idle');setHandoffUrl('')}}>{c.newIdea}</button><a className="secondary" href={`/${locale}/contact`}>{c.contact} ↗</a></footer>
    </article>
  }
  const x=conversionCopy[locale]??conversionCopy.en;
  const loading=loadingCopy[locale]??loadingCopy.en;
  return <form className="trip-planner" onSubmit={submit} aria-busy={status==='loading'}><header><div><span className="agent-mark">Journey Designer · Way to Asia</span><h2>{c.start}</h2><p>{c.intro}</p></div><div className="planner-promise"><b>{x.nextTitle}</b><span>01 · {x.nextOne}</span><span>02 · {x.nextTwo}</span><span>03 · {x.nextThree}</span></div></header><div className="planner-grid"><fieldset className="wide"><legend>{c.where}</legend><label className="choice"><input type="checkbox" name="destinations" value="" defaultChecked/><span>{a.anywhere}</span></label>{destinations.map(([value,label])=><label className="choice" key={value}><input type="checkbox" name="destinations" value={value}/><span>{label}</span></label>)}</fieldset><label className="wide prompt-field">{a.destinationIdeas}<textarea name="destinationIdeas" rows={2} maxLength={180} placeholder={a.destinationPlaceholder}/></label><label>{c.when}<input type="month" name="travelMonth"/></label><label>{c.days}<output>{duration}</output><input type="range" min="5" max="35" value={duration} onChange={event=>setDuration(Number(event.target.value))}/></label><fieldset><legend>{c.travellers}</legend><div className="inline-fields"><label>{c.adults}<input type="number" name="adults" min="1" max="12" defaultValue="2" required/></label><label>{c.children}<input type="number" name="children" min="0" max="8" defaultValue="0" required/></label></div></fieldset><label>{c.budget}<select name="budget" defaultValue="comfort"><option value="value">{c.value}</option><option value="comfort">{c.comfort}</option><option value="premium">{c.premium}</option><option value="luxury">{c.luxury}</option><option value="unsure">{c.unsure}</option></select></label><label>{c.pace}<select name="pace" defaultValue="balanced"><option value="slow">{c.slow}</option><option value="balanced">{c.balanced}</option><option value="active">{c.active}</option></select></label><fieldset className="wide"><legend>{c.interests}</legend>{interestKeys.map(key=><label className="choice" key={key}><input type="checkbox" name="interests" value={key}/><span>{c[key]}</span></label>)}</fieldset><label className="wide prompt-field">{c.notes}<textarea name="notes" rows={4} maxLength={1000} placeholder={c.placeholder}/></label></div><div className="planner-submit"><p>{c.notice}</p><button className="btn" type="submit" disabled={status==='loading'}>{status==='loading'?c.working:c.submit} ↗</button></div>{status==='loading'&&<section className="planner-loading" data-planner-loading role="status" aria-live="polite"><div className="loading-compass" aria-hidden="true"><span/><i/></div><div className="loading-story"><span className="agent-mark">Journey Designer · working</span><h3>{loading.title}</h3><p>{loading.intro}</p><div className="loading-track" aria-hidden="true"><span/></div><ol>{loading.stages.map((stage,index)=><li className={index<loadingStep?'done':index===loadingStep?'active':''} key={stage}><span>{index<loadingStep?'✓':String(index+1).padStart(2,'0')}</span><b>{stage}</b></li>)}</ol><small>{loading.keepOpen}</small></div></section>}{error&&<p className="form-error" role="alert">{error}</p>}</form>;
}
